 "content": "def transform(grid):
    """Copy the five-cell horizontal template around each isolated marker."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    # Locate the contiguous horizontal five-cell exemplar.
    template = None
    for r, row in enumerate(g):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start == 5:
                template = row[start:c]
                break
        if template is not None:
            break
    if template is None:
        return g
    colors = set(template)
    # Isolated marker color is the non-background color outside the template.
    template_cells = {(r, c) for r, row in enumerate(g) for c, v in enumerate(row)
                      if v != bg and any(row[max(0,c-4):min(w,c+5)])}
    counts = {}
    for r, row in enumerate(g):
        for c, v in enumerate(row):
            if v != bg and v not in colors:
                counts[v] = counts.get(v, 0) + 1
    # Choose the most frequent color not used by the exemplar (the scattered markers).
    if not counts:
        return g
    marker = max(counts, key=counts.get)
    markers = [(r, c) for r, row in enumerate(g) for c, v in enumerate(row) if v == marker]
    for r, c in markers:
        start = c - 2
        for j, val in enumerate(template):
            if 0 <= start + j < w:
                g[r][start + j] = val
    return g
